/** Tool name → the tagged API methods and the doc summaries agents read. */
export const TOOL_DOCS: ReadonlyMap<string, readonly { api: string; summary: string }[]> =
  new Map([
    ["add_build", [{"api":"KeynoteSlide.addBuild","summary":"Animate a drawable on this slide: an all-at-once build in the shape the app writes, played on click. Keynote has not yet been seen to play a build this library wrote from nothing; see docs/VERIFICATION.md."}]],
    ["add_category", [{"api":"TableModel.addCategory","summary":"Group the table's rows by the values in one column, or nest groups by several columns in the order given; a level given as `{ column, bucket }` groups a date column by year, month, quarter, week, day or weekday, with the app's own bucketing formula. Defines a by-value category — one group per distinct value at each level, listed in text order, each holding its rows — in the shape every categorised table in the corpus has, and switches it on. The table must not be categorised already (`regroupCategories` maintains an existing definition), and every data row needs a value in each column. The app has not yet been seen to draw a category this library defined; see docs/VERIFICATION.md."}]],
    ["add_filter_rule", [{"api":"TableModel.addFilterRule","summary":"Add a row-filter rule: show rows whose cell in `column` (absolute; column 0 is refused, see below) compares to `value` as `operator` says, or contains it as text when the operator is \"contains\". The rule is written the way a rule the app wrote is carried — the comparison in the predicate and as a formula over the table's own identity, both counted from the app's host column — the set is switched on, and the rows the set now hides are written to the hidden-state extent, evaluated here. The app has not yet been seen to open a filter written this way; see docs/VERIFICATION.md."}]],
    ["add_image", [{"api":"PagesDocument.insertInlineImage","summary":"Insert an image inline at a body-text position. Registers the bytes as a Data/ file (SHA-1 deduped), creates the TSD.ImageArchive + attachment objects, anchors them at a U+FFFC character, and sizes the image from its intrinsic dimensions — PNG/JPEG/GIF pixels, or a PDF's first-page MediaBox in points — scaled to fit `maxWidth` (default 400 pt) unless explicit width/height are given. A PDF is media like any raster image: the corpus's PDF figures use the same archive, and stay vector when the app scales them. App-confirmed: ladder rung P11 renders at the size asked. The image rides the text: it sits in the text column and moves with the paragraph's indent, because the drawable carries the in-the-text-flow `exterior_text_wrap`. Pass `wrap: \"page\"` for the other behaviour, where the image is placed against the page margins and text flows around it — with an indented body that means the picture will not line up with the words above it."},{"api":"KeynoteDocument.addImage","summary":"Put a picture on a slide. The archive is the measured slide-image shape, unanimous across the corpus's 22: the drawable's parent is the slide, the exterior wrap is the on-page shape, the aspect ratio is locked, stand-in title and caption ride along, and the style is the theme's `image-0-imageStyle` media style. The image lands in the slide's own package component beside its other content and joins both drawable lists — ownership and paint order. Sized like `insertInlineImage`: explicit `width`/`height` win, otherwise the intrinsic size is fitted to `maxWidth` (default 400 pt). Unless `x`/`y` say otherwise the picture is centered on the slide."}]],
    ["add_table", [{"api":"PagesDocument.insertInlineTable","summary":"Insert a table inline at a body-text position, cloned from a table already in the document. Clone-based like `NumbersDocument.addTable`, because a table's object graph — model, data store, tiles, data lists, per-band styles — is far beyond what can be invented safely; every identity in the copy comes from an Apple-authored source. A document with no table gets the neutral table every app shares — the blank Numbers document's own, Apple-made — grafted in. `rows` fits and fills the table. The copy forks its data lists (the clone walk follows the whole table subtree), so filling it never touches the source — the save-time integrity gate would refuse the file if it did. The anchoring is the measured inline-table shape: the info's `parent` is the body storage, its geometry sits at the origin with the standard flags, and a five-field attachment ties it to a U+FFFC character."},{"api":"KeynoteSlide.addTable","summary":"Put a table on the slide: the neutral table every app shares (the blank Numbers document's own, Apple-made), its parent the slide, in both of the slide's drawable lists like the corpus's slide tables. `rows` fits and fills it; `name` is made unique among the deck's tables; `x` and `y` place it, else it keeps the donor's position."}]],
    ["add_text_box", [{"api":"PagesDocument.addTextBox","summary":"Put a floating text box on a page, saying `text`, placed and sized by `placement` (points; the donor's size otherwise). The box is a deep copy of a text box the document already carries — the page's first, else any page's — so it has the document's own style, its own storage and every field the app writes; a document with no text box (the blank has none) cannot grow one this way. Pages has not yet been seen to open a box added this way; see docs/VERIFICATION.md."},{"api":"KeynoteSlide.addTextBox","summary":"Put a text box on this slide, saying `text`, placed and sized by `placement` (points; the donor's size otherwise). The box is a deep copy of a text box the deck already carries — this slide's first, else any slide's or master's — so it has the theme's own style, its own storage and every field the app writes. Keynote has not yet been seen to open a box added this way; see docs/VERIFICATION.md."}]],
    ["append_paragraph", [{"api":"PagesDocument.appendParagraph","summary":"Append a paragraph to the body. `style` may be a style name (\"Heading 1\") or a style object id. Returns the new paragraph index. `list` names a list style (\"Bullet\", \"Numbered\") to make the paragraph a list item; without it the paragraph is not one, whatever the paragraph before it was."}]],
    ["audit_document", [{"api":"IWorkDocument.audit","summary":"Every fault this library knows how to recognise offline, across the whole document — the checks a person otherwise performs by opening the file in an app. Each finding names a state some review round has already watched an app refuse, repair destructively, or render against the author's intent. `save()` refuses the `error` classes it can see; `audit()` reports them without saving, warnings included, so a builder can ask \"what would a person object to?\" before shipping a document."}]],
    ["create_document", [{"api":"PagesDocument.blank","summary":"A new, empty Pages document — A4, vanilla styling, no template file needed. The embedded donor is an Apple-written corpus fixture emptied by blankFrom and re-papered to A4 with byte-measured values, so every style and identity in the \"new\" document was authored by an Apple app. `scripts/make-blanks.ts` records its provenance."},{"api":"PagesDocument.fromMarkdown","summary":"A new document written from Markdown: headings become the template's Title, Heading, Heading 2 and Heading 3 paragraphs (deeper levels share Heading 3), paragraphs Body, bullet and numbered lists Body items with the Bullet or Numbered list style, block quotes Body paragraphs, each pipe table an inline table in a paragraph of its own, and each image on a line of its own an inline picture, when `images` supplies its bytes by the source the Markdown names. Links become hyperlinks and footnote references with a definition become footnotes, and bold and italic direct formatting."},{"api":"NumbersDocument.blank","summary":"A new, empty Numbers spreadsheet — one sheet, one table, A4 paper, no template file needed. The embedded donor is an Apple-written corpus fixture (already `iso-a4`) emptied by blankFrom, so every style and identity in the \"new\" document was authored by an Apple app. `scripts/make-blanks.ts` records its provenance."},{"api":"KeynoteDocument.blank","summary":"A new, empty Keynote deck — one slide, 16:9 (1920 × 1080), no template file needed. The embedded donor is an Apple-written corpus fixture emptied by blankFrom, so every master, style, and identity in the \"new\" deck was authored by an Apple app. `scripts/make-blanks.ts` records its provenance."}]],
    ["export_document", [{"api":"IWorkDocument.toMarkdown","summary":"The document as Markdown: paragraphs as paragraphs, headings by their named style, list paragraphs as list items, tables as pipe tables and charts as a table of their series. Pages, Numbers and Keynote each arrange this in their own structure — body, sheets, slides. Pictures are written through `images`, a sink that places each one and returns its link; without it they are left out."},{"api":"TableModel.toCsv","summary":"The table's cells as CSV (RFC 4180): one line per row, fields quoted when they hold a comma, a quote or a line break. Formulas give their cached value, like cellText."}]],
    ["format_cells", [{"api":"TableModel.setRangeFormatting","summary":"Apply the same formatting to a rectangular block of cells — fill, borders, padding, alignment, wrap — leaving every cell's value untouched."}]],
    ["format_text", [{"api":"PagesDocument.applyCharacterFormatting","summary":"Apply direct character formatting to a body range: creates an anonymous TSWP.CharacterStyleArchive (parented on the effective style at `start`) and spans it over [start, end). Returns the new style's id."}]],
    ["insert_link", [{"api":"PagesDocument.insertLink","summary":"Make a body range a hyperlink."}]],
    ["list_comments", [{"api":"TableModel.cellComment","summary":"The comment on one cell, if the app left one there."},{"api":"TableModel.cellComments","summary":"Every comment on this table's cells, in row-major order. Comments are the app's own annotation channel and the review loop's reply channel: a returned file carries its findings here, so a reading that skips them reads a clean file where the verdict sits. The library reads and preserves them — writing one is the app's job."}]],
    ["list_formulas", [{"api":"TableModel.formulas","summary":"Every formula cell in the table, with its rendered text. Walks the row records for a formula id rather than going through cells: a formula the app wrote carries a cached value, but a freshly authored one does not until the app recomputes, and it is a formula either way."}]],
    ["manage_sheets", [{"api":"NumbersDocument.addSheet","summary":"Add a sheet by copying an existing one. A sheet is a container for drawables, and a Numbers document with an empty one is perfectly valid — but the *tables* on a sheet are what make it useful, and building a table from nothing means synthesising tiles, header buckets, data lists and a calc-engine owner. Copying is both simpler and closer to what Numbers does when you duplicate a tab. By default the copy keeps its tables (a duplicate); pass `withContent: false` for an empty sheet."},{"api":"NumbersDocument.addTable","summary":"Add a table to a sheet. Building a table from nothing means synthesising tiles, header buckets, data lists and a calc-engine owner — the same reason sheets and slides are created by copying. Without `copyOf`, the source is the **embedded Apple-made blank table** (the same donor `blank()` documents are born with): the new table arrives empty and neutrally styled, inheriting nobody's widths, fills or wrap styles. Pass `copyOf` to duplicate a table already in the document instead. The copy is renamed, because **Numbers addresses tables by name**: two tables called \"Table 1\" on one sheet make every cross-table formula ambiguous. Names must be unique per sheet, not per document, so a copy onto a different sheet can keep the original's name. `withContent: false` clears a `copyOf` duplicate's cells but keeps the shape, styling and header bands. Either way, what the new table keeps is the caller's decision: row and column count and widths arrive at the donor's shape and rarely fit the new table as they are."},{"api":"NumbersDocument.moveSheet","summary":"Move a sheet to a new position in tab order."},{"api":"NumbersDocument.removeSheet","summary":"Remove a sheet from the document's tab order."},{"api":"NumbersDocument.renameSheet","summary":"Rename a sheet. Names must be unique, as they are in the app."},{"api":"NumbersDocument.setActiveSheet","summary":"Make a sheet the one the document opens on. Numbers remembers the selected tab in its UI state — every `TN.SheetSelectionArchive` names a sheet through a reference — and ignores tab order when deciding where to open, so a document rearranged with moveSheet still opens on whatever sheet was active at the last save. This re-points every stored sheet selection at the given sheet."}]],
    ["manage_slides", [{"api":"KeynoteDocument.addSlide","summary":"Add a slide, copying an existing one. Keynote slides are not blank canvases — a usable one carries a style, a template-slide reference, placeholders and a transition, and inventing that set from nothing produces a slide the app quietly repairs or rejects. Copying an existing slide inherits a working set, which is also how Keynote's own \"new slide\" works: it instantiates a master. `after` is a slide index; -1 puts the new slide first. By default the copy is emptied of its drawables, giving a fresh slide on the same layout; pass `withContent` to duplicate outright. `master` instead instantiates a layout — one of masterSlides, by name or id — the way the app's \"add slide\" does: the master is deep-copied, its decorations and placeholders included, and the copy is made a content slide. The corpus states the difference between a content slide and its master exactly: the slide carries a reference to the master, a note, and the slide-number placeholder's storage holds the number attachment; it never carries the master's name, object placeholder, style lists or thumbnail texts. The title and body are emptied like a copied slide's."},{"api":"KeynoteDocument.duplicateSlide","summary":"Duplicate a slide, content and all."},{"api":"KeynoteDocument.moveSlide","summary":"Move a slide to a new position in presentation order."},{"api":"KeynoteDocument.removeSlide","summary":"Remove a slide from the presentation. Only the tree entry is removed. The slide archive itself is left in the package: other objects may still reference it, and this library never garbage-collects the object graph — an orphan is inert, a dangling reference is not."},{"api":"KeynoteDocument.setSlideSize","summary":"Resize the slide canvas. Changes the coordinate space every drawable on every slide sits in, and nothing is rescaled to match: a deck resized from 1920×1080 to 1024×768 keeps its objects where they were, which is what Keynote's own \"change slide size\" does before you rearrange."}]],
    ["merge_cells", [{"api":"TableModel.mergeCells","summary":"Merge a rectangle of cells, anchored at its top-left. A merge is not a property of the cells. It is a **formula owned by the calc engine**: `TableModelArchive.merge_owner.formula_store` holds one colon-tract AST node per merged rectangle, and the covered cells are simply deleted — Apple leaves them with no record at all, which is why `cellValue` returns `undefined` for them rather than \"empty\". Every table in every document examined already carries a `merge_owner` with an owner id, merged or not, so nothing here has to mint a calc engine identity. A table that somehow lacks one is refused rather than guessed at: an owner the engine does not know about is worse than no merge, because the document would load and then behave oddly. The anchor's value survives; everything the rectangle covers is discarded, exactly as merging does in the app."},{"api":"TableModel.unmergeCells","summary":"Remove the merge anchored at a cell, returning false if there is none. The cells it covered come back empty, which is what the app does: the values they held before merging were discarded at merge time and are not recoverable from the file."}]],
    ["modify_table", [{"api":"TableModel.deleteColumns","summary":"Delete columns starting at `at`."},{"api":"TableModel.deleteRows","summary":"Delete rows starting at `at`."},{"api":"TableModel.insertColumns","summary":"Insert blank columns before `at`."},{"api":"TableModel.insertRows","summary":"Insert blank rows before `at`. The whole table's storage is rebuilt rather than patched: tiles, row headers and per-column cell counts all have to agree afterwards, and shifting them independently is how those three drift apart. **Formula references are not adjusted.** Relative references survive by construction — they are offsets from the cell using them, so a formula that moves keeps pointing at the same relative neighbour — but an absolute range spanning the insertion point still names its old bounds. Adjusting those correctly is calc-engine work; see docs/FORMAT.md §14.7."},{"api":"TableModel.setColumnWidth","summary":"Set one column's width in points."},{"api":"TableModel.setRowHeight","summary":"Set an explicit row height; 0 restores the table default."}]],
    ["replace_text", [{"api":"PagesDocument.replaceText","summary":"Literal find/replace across the body, preserving the styling of the surrounding text. Returns how many occurrences changed."}]],
    ["set_cell_format", [{"api":"TableModel.setCellFormat","summary":"Set how a cell's value is displayed. A cell shows one format, so any format the record already carried is cleared first — leaving a stale currency id beside a new date id would make the display depend on which flag the app happens to read first."},{"api":"TableModel.setRangeFormat","summary":"Apply one format across a rectangular block."}]],
    ["set_cells", [{"api":"TableModel.setCell","summary":"Write a value into an existing cell. Presentation the record already carries — cell and text style ids, number formats, comments, conditional styles — is preserved, except that format ids tied to the *old* value type are dropped when the type changes (a date format on a number cell would render nonsense). Writing a literal also clears any formula on the cell. Rich text (`{ type: \"richText\" }`) cannot be written: the value lives in a separate TSWP storage object. Set plain `text` instead, or edit the existing rich-text storage through richTextStorage."}]],
    ["set_formula", [{"api":"TableModel.setFormula","summary":"Write a formula into a cell. The formula is compiled to a TSCE AST, interned in the table's formula table, and the cell's record points at it — the same three steps the app performs. Relative references are stored as offsets from this cell, so `=A1+1` in B2 and in B3 compile to different bytes, exactly as in the app. **Nothing here evaluates.** A cell record carries the formula *and* its cached result, and the apps display the cache until the engine recalculates. `value` is that cache: supply it and the cell reads correctly before any app has touched the file; omit it and whatever the cell held is kept, which is right when the formula reproduces the value already there and wrong otherwise. There is no third option that does not involve implementing Apple's calc engine. **The dependency tracker is not written — and does not need to be.** The calc engine keeps its own per-cell ledger (`TSCE.FormulaOwnerDependenciesArchive`) that this method leaves alone. Numbers rebuilds it on open rather than trusting it: the e2e recompute probe writes a formula with a deliberately wrong cached value and the app reports the recomputed result on every `npm run test:e2e`. Refuses a function it has no index for rather than inventing one — see `authorableFunctions()` for the 272 it knows."}]],
    ["set_page_setup", [{"api":"PagesDocument.setPageSetup","summary":"Update page geometry (points; 1 pt = 1/72 in). Only given fields change."}]],
    ["set_slide_background", [{"api":"KeynoteSlide.setBackground","summary":"Set the slide's background, copying on write. A per-slide background is a KN.SlideStyleArchive beside the master's in the stylesheet's component: unnamed, a variation whose parent is the master's style and whose stylesheet is the document's, override count 1, and the fill in its slide properties. Nothing lists it; the slide's own reference is its only referrer. A slide already carrying such a variation of its own has the fill replaced in place; one sharing its style with the master, or with other slides, gets a variation of its own."}]],
    ["set_table_bands", [{"api":"TableModel.setBands","summary":"Change how many leading rows/columns are header bands, and how those bands behave. Bands are presentation only — cell storage is identical either way — so this is a safe edit that does not touch the tiles. Counts are clamped to the table's real size: a header count past the last row would leave the app with no body."}]],
  ]);

